{"results": [{"id": "hp_doc_46d0707fe0ce4f16253a58696582a1220560a7740fef8403ae504c08a00c13ed", "title": "Clark Island (New South Wales)", "text": "Clark Island is a small island in Sydney Harbour, near the coast of New South Wales, Australia. The island is part of the Sydney Harbour National Park and lies offshore the Sydney suburb of Darling Point, in the eastern part of Sydney Harbour between the Harbour Bridge and the harbour entrance.", "score": 21.7067}, {"id": "hp_doc_7084be712119ec7facf569c52f241ae2217256454be0438b509ff740e7de9376", "title": "Clark Island (Washington)", "text": "Clark Island is an island in the San Juan Islands of the U.S. state of Washington. It is located near Barnes Island off the northeast coast of Orcas Island. Clark Island State Park, which encompasses the entire 55 acre island, has two picnicking sites, 15 primitive campsites, and nine mooring buoys.", "score": 17.6011}, {"id": "hp_doc_f857d1486be3e2ba534ef9266c7125da078848b2b7bc7c9f0637f083d52fe933", "title": "Barnes Island", "text": "Barnes Island is a small island in the San Juan Islands of the U.S. state of Washington. It is located near Clark Island off the northeast coast of Orcas Island.", "score": 15.3093}], "remaining_searches": 2}
